#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;int n=s.size();bool ok=false;
for(int L=1;L<=n/2;++L){if(n%L)continue;
bool good=true;
for(int i=L;i<n&&good;++i)if(s[i]!=s[i-L])good=false;
if(good){ok=true;break;}}
printf("%s\n",ok?"YES":"NO");return 0;}

